<?php

if ( PHP_SAPI !== 'cli' ) { http_response_code( 404 ); exit; }
$checks = 0;
function dsri_check( $condition, $message ) { global $checks; $checks++; if ( ! $condition ) { throw new RuntimeException( 'FAIL ' . $message ); } echo "PASS  $message\n"; }
$schema = file_get_contents( dirname( __DIR__ ) . '/src/Infrastructure/Database/SchemaManager.php' );
$reserved = array_flip( preg_split( '/\s+/', trim( 'ACCESSIBLE ADD ALL ALTER ANALYZE AND AS ASC ASENSITIVE BEFORE BETWEEN BIGINT BINARY BLOB BOTH BY CALL CASCADE CASE CHANGE CHAR CHARACTER CHECK COLLATE COLUMN CONDITION CONSTRAINT CONTINUE CONVERT CREATE CROSS CURRENT_DATE CURRENT_ROLE CURRENT_TIME CURRENT_TIMESTAMP CURRENT_USER CURSOR DATABASE DATABASES DAY_HOUR DAY_MICROSECOND DAY_MINUTE DAY_SECOND DEC DECIMAL DECLARE DEFAULT DELAYED DELETE DELETE_DOMAIN_ID DESC DESCRIBE DETERMINISTIC DISTINCT DISTINCTROW DIV DO_DOMAIN_IDS DOUBLE DROP DUAL EACH ELSE ELSEIF ENCLOSED ESCAPED EXCEPT EXISTS EXIT EXPLAIN FALSE FETCH FLOAT FLOAT4 FLOAT8 FOR FORCE FOREIGN FROM FULLTEXT GENERAL GRANT GROUP HAVING HIGH_PRIORITY HOUR_MICROSECOND HOUR_MINUTE HOUR_SECOND IF IGNORE IGNORE_DOMAIN_IDS IGNORE_SERVER_IDS IN INDEX INFILE INNER INOUT INSENSITIVE INSERT INT INT1 INT2 INT3 INT4 INT8 INTEGER INTERSECT INTERVAL INTO IS ITERATE JOIN KEY KEYS KILL LEADING LEAVE LEFT LIKE LIMIT LINEAR LINES LOAD LOCALTIME LOCALTIMESTAMP LOCK LONG LONGBLOB LONGTEXT LOOP LOW_PRIORITY MASTER_HEARTBEAT_PERIOD MASTER_SSL_VERIFY_SERVER_CERT MATCH MAXVALUE MEDIUMBLOB MEDIUMINT MEDIUMTEXT MIDDLEINT MINUTE_MICROSECOND MINUTE_SECOND MOD MODIFIES NATURAL NOT NO_WRITE_TO_BINLOG NULL NUMERIC OFFSET ON OPTIMIZE OPTION OPTIONALLY OR ORDER OUT OUTER OUTFILE OVER PAGE_CHECKSUM PARSE_VCOL_EXPR PARTITION PRECISION PRIMARY PROCEDURE PURGE RANGE READ READS READ_WRITE REAL RECURSIVE REF_SYSTEM_ID REFERENCES REGEXP RELEASE RENAME REPEAT REPLACE REQUIRE RESIGNAL RESTRICT RETURN RETURNING REVOKE RIGHT RLIKE ROW_NUMBER ROWS SCHEMA SCHEMAS SECOND_MICROSECOND SELECT SENSITIVE SEPARATOR SET SHOW SIGNAL SLOW SMALLINT SPATIAL SPECIFIC SQL SQLEXCEPTION SQLSTATE SQLWARNING SQL_BIG_RESULT SQL_CALC_FOUND_ROWS SQL_SMALL_RESULT SSL STARTING STATS_AUTO_RECALC STATS_PERSISTENT STATS_SAMPLE_PAGES STRAIGHT_JOIN TABLE TERMINATED THEN TINYBLOB TINYINT TINYTEXT TO TRAILING TRIGGER TRUE UNDO UNION UNIQUE UNLOCK UNSIGNED UPDATE USAGE USE USING UTC_DATE UTC_TIME UTC_TIMESTAMP VALUES VARBINARY VARCHAR VARCHARACTER VARYING WHEN WHERE WHILE WINDOW WITH WRITE XOR YEAR_MONTH ZEROFILL' ) ) );
$violations = array();
if ( preg_match_all( '/\$tables\[\'([^\']+)\'\]\s*=\s*"CREATE TABLE.*?\((.*?)\) ENGINE=InnoDB/s', $schema, $matches, PREG_SET_ORDER ) ) {
    foreach ( $matches as $match ) {
        foreach ( preg_split( '/\R/', $match[2] ) as $line ) {
            $line = trim( $line );
            if ( '' === $line ) { continue; }
            $token = strtoupper( preg_replace( '/[^A-Za-z0-9_].*/', '', $line ) );
            if ( in_array( $token, array( 'PRIMARY', 'UNIQUE', 'KEY', 'CONSTRAINT', 'FOREIGN' ), true ) ) { continue; }
            if ( isset( $reserved[ $token ] ) ) { $violations[] = strtolower( $match[1] . '.' . $token ); }
        }
    }
}
dsri_check( empty( $violations ), 'all future-domain column identifiers avoid MariaDB 10.11 reserved words: ' . implode( ', ', $violations ) );
dsri_check( false === strpos( $schema, "\n\t\t\tcursor BIGINT" ), 'jobs.cursor remains absent from future-domain DDL' );
dsri_check( false === strpos( $schema, "\n\t\t\trow_number BIGINT" ), 'import_rows.row_number is absent from future-domain DDL' );
echo "SUMMARY $checks checks, 0 failures\n";
